G("distribucion-binomial-explicada", "La distribución binomial explicada",
  "Distribución Binomial: Fórmula, Ejemplos y Cómo Calcular Probabilidades | Calculadora Científica",
  "Qué es la distribución binomial, cuándo se usa, la fórmula de la probabilidad, ejemplos resueltos con monedas y exámenes, probabilidades acumuladas, media y desvío.",
  "Binomial: fórmula, ejemplos resueltos y probabilidades acumuladas.",
  "La distribución binomial explicada con ejemplos",
  "La binomial responde una pregunta muy común: si repito algo n veces, ¿cuál es la probabilidad de lograr exactamente k éxitos? Sirve para monedas, exámenes de opción múltiple y control de calidad.",
  "P(X = k) = C(n, k)·p^k·(1 − p)^(n−k). Media n·p; desvío √(n·p·(1 − p)).",
  (E + "distribucion-binomial/", "Abrir calculadora"),
  [g_h2("1. Cuándo se usa"), g_ul(["Una cantidad fija de ensayos (n).", "Cada ensayo tiene solo dos resultados: éxito o fracaso.", "La probabilidad de éxito (p) es la misma en todos.", "Los ensayos son independientes."]),
   g_h2("2. La fórmula"), g_formula("P(X = k) = C(n, k) · p<sup>k</sup> · (1 − p)<sup>n − k</sup>"), g_p("C(n, k) = n! / (k!·(n − k)!) cuenta de cuántas formas se pueden ubicar los k éxitos entre los n ensayos."),
   g_h2("3. Ejemplo: 10 monedas"), g_steps(["¿Probabilidad de exactamente 5 caras en 10 tiradas? n = 10, p = 0,5, k = 5", "C(10, 5) = 252", "P = 252 × 0,5⁵ × 0,5⁵ = 252 / 1024 = 24,6 %"]),
   g_h2("4. Probabilidades acumuladas"), g_p("P(X ≤ k) es la suma de las probabilidades de 0 a k. Con las 10 monedas, P(X ≤ 5) = 62,3 %. Y P(X ≥ k) = 1 − P(X ≤ k − 1)."),
   g_h2("5. Ejemplo: un examen al azar"), g_steps(["10 preguntas con 4 opciones: p = 0,25 por pregunta", "¿7 aciertos contestando al azar? C(10, 7) = 120", "P = 120 × 0,25⁷ × 0,75³ = 0,31 %"]),
   g_p("Aprobar con 7 aciertos adivinando es muy improbable."),
   g_h2("6. Media y desvío"), g_p("Se esperan n·p éxitos. Con 20 ensayos al 30 %, la media es 6 y el desvío √(20 × 0,3 × 0,7) = 2,05."),
   g_h2("7. Errores comunes"), g_ul(["Usarla cuando los ensayos no son independientes (extraer sin reposición de una población chica).", "Confundir P(X = k) con P(X ≤ k).", "Poner la probabilidad en porcentaje dentro de la fórmula (hay que usar 0,25, no 25)."])],
  [("¿Cómo se calcula la probabilidad binomial?", "Con C(n, k)·p^k·(1 − p)^(n−k). 5 caras en 10 monedas: 24,6 %."), ("¿Qué es P(X ≤ k)?", "La probabilidad acumulada de k éxitos o menos."),
   ("¿Cuál es la media?", "n·p."), ("¿Cuándo no se puede usar?", "Si los ensayos no son independientes o la probabilidad cambia entre ellos.")],
  [(E + "distribucion-binomial/", "Calculadora de Distribución Binomial"), (E + "permutaciones-y-combinaciones/", "Permutaciones y Combinaciones"), ("/guias/permutaciones-vs-combinaciones/", "Guía: permutaciones vs combinaciones")])

G("intervalo-de-confianza-explicado", "El intervalo de confianza explicado",
  "Intervalo de Confianza para la Media: Fórmula, z vs t e Interpretación | Calculadora Científica",
  "Qué es un intervalo de confianza, cómo calcularlo para la media con z o t de Student, cómo interpretarlo correctamente, el margen de error y un ejemplo resuelto.",
  "Intervalo de confianza: fórmula, z vs t y cómo interpretarlo.",
  "El intervalo de confianza explicado paso a paso",
  "Una media calculada con una muestra casi nunca coincide con la de toda la población. El intervalo de confianza da un rango razonable donde está la media verdadera.",
  "x̄ ± c · s/√n, con c = z (normal) o t de Student si el desvío es muestral y n ≤ 30. Al 95 %, z = 1,96.",
  (E + "intervalo-de-confianza/", "Abrir calculadora"),
  [g_h2("1. La fórmula"), g_formula("x̄ ± c · s / √n"), g_p("x̄ es la media de la muestra, s el desvío, n el tamaño y c el valor crítico del nivel de confianza. A s/√n se lo llama error estándar."),
   g_h2("2. z o t"), g_table(["Confianza", "z", "t (n = 25)"], [["90 %", "1,645", "1,711"], ["95 %", "1,960", "2,064"], ["99 %", "2,576", "2,797"]]),
   g_p("Se usa z si el desvío poblacional es conocido o la muestra es grande (n > 30). Con muestras chicas y desvío muestral se usa t de Student, que da intervalos algo más anchos."),
   g_h2("3. Ejemplo con muestra grande"), g_steps(["Media 50, desvío 10, n = 100, confianza 95 %", "Error estándar = 10 / √100 = 1", "Margen = 1,96 × 1 = 1,96", "Intervalo: [48,04 ; 51,96]"]),
   g_h2("4. Ejemplo con muestra chica"), g_steps(["Media 50, desvío muestral 10, n = 25, confianza 95 %", "t con 24 grados de libertad = 2,064", "Margen = 2,064 × 10 / 5 = 4,13", "Intervalo: [45,87 ; 54,13]"]),
   g_h2("5. Cómo interpretarlo"), g_p("\"Con 95 % de confianza, la media está entre 48,04 y 51,96\" significa que el método usado captura la media verdadera en el 95 % de las muestras. No es la probabilidad de que esta media en particular esté ahí."),
   g_h2("6. Cómo achicar el intervalo"), g_ul(["Aumentar el tamaño de la muestra (el margen baja con la raíz de n).", "Bajar el nivel de confianza (a costa de menos seguridad).", "Tener menos variabilidad en los datos."])],
  [("¿Cómo se calcula el intervalo de confianza?", "x̄ ± c·s/√n."), ("¿Cuándo uso t de Student?", "Con desvío muestral y n ≤ 30."), ("¿Qué es el margen de error?", "c·s/√n: la mitad del ancho del intervalo."), ("¿Cómo lo interpreto?", "Es el rango donde, con el nivel de confianza elegido, está la media verdadera.")],
  [(E + "intervalo-de-confianza/", "Calculadora de Intervalo de Confianza"), (E + "tamano-de-muestra/", "Tamaño de Muestra"), ("/guias/como-calcular-desviacion-estandar/", "Guía: desviación estándar")])

G("como-calcular-el-tamano-de-una-muestra", "Cómo calcular el tamaño de una muestra",
  "Cómo Calcular el Tamaño de una Muestra: Fórmula y Ejemplos | Calculadora Científica",
  "Cómo calcular cuántas personas encuestar para estimar una proporción según el nivel de confianza y el margen de error, con la corrección por población finita y ejemplos.",
  "Tamaño de muestra: fórmula, corrección por población finita y tabla.",
  "Cómo calcular el tamaño de una muestra",
  "Antes de hacer una encuesta hay que decidir a cuántas personas preguntar: pocas dan resultados poco confiables y muchas encarecen el estudio. La fórmula para proporciones lo resuelve.",
  "n = z²·p·(1 − p) / e². Con 95 % de confianza, p = 50 % y error de 5 % hacen falta 385 personas.",
  (E + "tamano-de-muestra/", "Abrir calculadora"),
  [g_h2("1. La fórmula"), g_formula("n₀ = z² · p · (1 − p) / e²"),
   g_ul(["z: valor crítico del nivel de confianza (1,645, 1,96 o 2,576).", "p: proporción esperada; si no la conocés, 0,5 (la peor situación, que da la muestra más grande).", "e: margen de error (por ejemplo 0,05)."]),
   g_steps(["95 % de confianza (z = 1,96), p = 0,5, e = 0,05", "n₀ = 1,96² × 0,5 × 0,5 / 0,05² = 384,16", "Se redondea hacia arriba: 385 personas"]),
   g_h2("2. Población finita"), g_formula("n = n₀ / (1 + (n₀ − 1) / N)"), g_p("Si la población es chica, la muestra necesaria baja. Para N = 1.000: n = 385 / (1 + 384/1000) = 278."),
   g_h2("3. Tabla de referencia (p = 50 %, población grande)"), g_table(["Confianza", "Error 5 %", "Error 3 %", "Error 10 %"], [["90 %", "271", "752", "68"], ["95 %", "385", "1.068", "97"], ["99 %", "664", "1.844", "166"]]),
   g_h2("4. Cómo bajar el tamaño de la muestra"), g_ul(["Aceptar un margen de error mayor (duplicarlo divide la muestra por cuatro).", "Bajar la confianza.", "Si tenés una estimación previa de p lejos del 50 %, usarla."]),
   g_h2("5. Para estimar una media"), g_p("La fórmula es n = (z·σ/e)², donde σ es el desvío estándar de la población y e el error absoluto aceptado. Esta guía y la calculadora tratan proporciones."),
   g_h2("6. Errores comunes"), g_ul(["Creer que la muestra debe ser un porcentaje de la población: lo que importa es el tamaño absoluto.", "Olvidar que una muestra grande no corrige un muestreo sesgado.", "No redondear hacia arriba."])],
  [("¿Cómo se calcula el tamaño de la muestra?", "n = z²·p·(1 − p)/e²."), ("¿Cuántas personas hay que encuestar con 95 % y 5 %?", "385."), ("¿Qué proporción uso si no la conozco?", "50 %."), ("¿Influye el tamaño de la población?", "Solo si es chica: se aplica la corrección por población finita.")],
  [(E + "tamano-de-muestra/", "Calculadora de Tamaño de Muestra"), (E + "intervalo-de-confianza/", "Intervalo de Confianza"), ("/guias/intervalo-de-confianza-explicado/", "Guía: el intervalo de confianza")])
